script.text:

function init$&Identity;Filter$(f) {
}
function active$&Identity;Filter$(f) {
	var g = f.grid, w = g.get_element().parentForm;

	f.add_commandEvent(on$&Identity;$ExecuteCommand);
	f.add_onResponseComplete(on$&Identity;$ResponseComplete);

	f.getItem('thanh_ly').focus();
}
function close$&Identity;Filter$(f) {
	try {f.remove_commandEvent(on$&Identity;$ExecuteCommand);} catch (ex) {}
	try {f.remove_onResponseComplete(on$&Identity;$ResponseComplete);} catch (ex) {}
}
function on$&Identity;$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid;
			var c = String.fromCharCode(255);
			f._$k = '';
			for(var i = 0; i < g._arrValue.length; i++) {
				f._$k += (f._$k != '' ? ',' : '') + g._arrValue[i][0][0];
			}

			f._checked = false;
			f.request('preSave', 'preSave', [['k', 'Infinite', f._$k]]);
			break;
		case 'preSave':
			if (result[0].Value == 1) {
				f.request('Save', 'Save', [['k', 'Infinite', f._$k], 'thanh_ly', 'ngay_tl']);
			} else {
				$message.show(result[1].Value);
			}
			break;
		case 'Save':
			on$&Identity;$TransferData(f, result);
			break;
		default:
			break;
	}
}
function on$&Identity;$ExecuteCommand(sender, e) {
	var action = e.type.Action, f = sender;
	switch (action) {
		default:
			break;
	}
}
function on$&Identity;$TransferData(f, a) {
	var g = f.grid;
	g._arrValue = [];
	g._focusWhenTabChanged();
	g.goToPage(-1);
	f.cancelDialog();
}
/* </flatten> */
